#![no_std]
use soroban_sdk::{
    contract, contracterror, contractimpl, contracttype, panic_with_error, token, Address, Env,
};

// Storage lifetime for persistent entries, in ledgers (about 5 seconds each).
const LEDGER_THRESHOLD: u32 = 17_280; // about 1 day
const LEDGER_BUMP: u32 = 535_680; // about 31 days

#[contracttype]
pub enum DataKey {
    /// The token contract staked (the native asset's Stellar Asset Contract on testnet).
    Token,
    /// Total amount staked by everyone.
    Total,
    /// Amount staked by one user.
    Staked(Address),
}

#[contracterror]
#[derive(Copy, Clone, Debug, Eq, PartialEq, PartialOrd, Ord)]
#[repr(u32)]
pub enum Error {
    InvalidAmount = 1,
    InsufficientStake = 2,
}

#[contract]
pub struct Staking;

fn token_address(env: &Env) -> Address {
    env.storage()
        .instance()
        .get(&DataKey::Token)
        .expect("token is set by the constructor")
}

fn read_staked(env: &Env, user: &Address) -> i128 {
    let key = DataKey::Staked(user.clone());
    if env.storage().persistent().has(&key) {
        env.storage()
            .persistent()
            .extend_ttl(&key, LEDGER_THRESHOLD, LEDGER_BUMP);
    }
    env.storage().persistent().get(&key).unwrap_or(0)
}

fn write_staked(env: &Env, user: &Address, amount: i128) {
    let key = DataKey::Staked(user.clone());
    env.storage().persistent().set(&key, &amount);
    env.storage()
        .persistent()
        .extend_ttl(&key, LEDGER_THRESHOLD, LEDGER_BUMP);
}

fn write_total(env: &Env, amount: i128) {
    env.storage().instance().set(&DataKey::Total, &amount);
}

fn read_total(env: &Env) -> i128 {
    env.storage().instance().get(&DataKey::Total).unwrap_or(0)
}

#[contractimpl]
impl Staking {
    /// Runs once, at deploy time. `token` is the token contract users stake.
    pub fn __constructor(env: Env, token: Address) {
        env.storage().instance().set(&DataKey::Token, &token);
        write_total(&env, 0);
        env.storage()
            .instance()
            .extend_ttl(LEDGER_THRESHOLD, LEDGER_BUMP);
    }

    /// Move `amount` of the token from `user` into the contract and credit it to `user`.
    pub fn stake(env: Env, user: Address, amount: i128) {
        user.require_auth();
        if amount <= 0 {
            panic_with_error!(&env, Error::InvalidAmount);
        }

        token::Client::new(&env, &token_address(&env)).transfer(
            &user,
            &env.current_contract_address(),
            &amount,
        );

        write_staked(&env, &user, read_staked(&env, &user) + amount);
        write_total(&env, read_total(&env) + amount);
    }

    /// Return `amount` of the user's stake to `user`. Fails if the user has less than `amount` staked.
    pub fn unstake(env: Env, user: Address, amount: i128) {
        user.require_auth();
        if amount <= 0 {
            panic_with_error!(&env, Error::InvalidAmount);
        }

        let staked = read_staked(&env, &user);
        if staked < amount {
            panic_with_error!(&env, Error::InsufficientStake);
        }

        write_staked(&env, &user, staked - amount);
        write_total(&env, read_total(&env) - amount);

        token::Client::new(&env, &token_address(&env)).transfer(
            &env.current_contract_address(),
            &user,
            &amount,
        );
    }

    /// The amount `user` has staked.
    pub fn staked(env: Env, user: Address) -> i128 {
        read_staked(&env, &user)
    }

    /// The amount staked by everyone.
    pub fn total_staked(env: Env) -> i128 {
        read_total(&env)
    }
}

mod test;
