#![cfg(test)]

use super::*;
use soroban_sdk::{testutils::Address as _, token::StellarAssetClient, token::TokenClient, Address, Env};

struct Setup<'a> {
    env: Env,
    client: StakingClient<'a>,
    token: TokenClient<'a>,
    token_admin: StellarAssetClient<'a>,
    contract_id: Address,
}

fn setup<'a>() -> Setup<'a> {
    let env = Env::default();
    env.mock_all_auths();

    let issuer = Address::generate(&env);
    let token_id = env.register_stellar_asset_contract_v2(issuer).address();
    let contract_id = env.register(Staking, (token_id.clone(),));

    Setup {
        client: StakingClient::new(&env, &contract_id),
        token: TokenClient::new(&env, &token_id),
        token_admin: StellarAssetClient::new(&env, &token_id),
        contract_id,
        env,
    }
}

#[test]
fn starts_empty() {
    let s = setup();
    let user = Address::generate(&s.env);
    assert_eq!(s.client.total_staked(), 0);
    assert_eq!(s.client.staked(&user), 0);
}

#[test]
fn stake_moves_tokens_and_records_stake() {
    let s = setup();
    let user = Address::generate(&s.env);
    s.token_admin.mint(&user, &1_000);

    s.client.stake(&user, &400);

    assert_eq!(s.client.staked(&user), 400);
    assert_eq!(s.client.total_staked(), 400);
    assert_eq!(s.token.balance(&user), 600);
    assert_eq!(s.token.balance(&s.contract_id), 400);
}

#[test]
fn stakes_accumulate_and_total_sums_users() {
    let s = setup();
    let alice = Address::generate(&s.env);
    let bob = Address::generate(&s.env);
    s.token_admin.mint(&alice, &500);
    s.token_admin.mint(&bob, &500);

    s.client.stake(&alice, &100);
    s.client.stake(&alice, &150);
    s.client.stake(&bob, &300);

    assert_eq!(s.client.staked(&alice), 250);
    assert_eq!(s.client.staked(&bob), 300);
    assert_eq!(s.client.total_staked(), 550);
}

#[test]
fn unstake_returns_tokens_and_reduces_stake() {
    let s = setup();
    let user = Address::generate(&s.env);
    s.token_admin.mint(&user, &1_000);
    s.client.stake(&user, &700);

    s.client.unstake(&user, &200);

    assert_eq!(s.client.staked(&user), 500);
    assert_eq!(s.client.total_staked(), 500);
    assert_eq!(s.token.balance(&user), 500);
    assert_eq!(s.token.balance(&s.contract_id), 500);
}

#[test]
fn unstake_everything() {
    let s = setup();
    let user = Address::generate(&s.env);
    s.token_admin.mint(&user, &1_000);
    s.client.stake(&user, &1_000);

    s.client.unstake(&user, &1_000);

    assert_eq!(s.client.staked(&user), 0);
    assert_eq!(s.client.total_staked(), 0);
    assert_eq!(s.token.balance(&user), 1_000);
}

#[test]
fn unstake_more_than_staked_fails() {
    let s = setup();
    let user = Address::generate(&s.env);
    s.token_admin.mint(&user, &1_000);
    s.client.stake(&user, &300);

    let result = s.client.try_unstake(&user, &301);

    assert_eq!(result, Err(Ok(Error::InsufficientStake)));
    assert_eq!(s.client.staked(&user), 300);
    assert_eq!(s.client.total_staked(), 300);
    assert_eq!(s.token.balance(&user), 700);
}

#[test]
fn unstake_without_any_stake_fails() {
    let s = setup();
    let user = Address::generate(&s.env);

    let result = s.client.try_unstake(&user, &1);

    assert_eq!(result, Err(Ok(Error::InsufficientStake)));
}

#[test]
fn cannot_unstake_another_users_stake() {
    let s = setup();
    let alice = Address::generate(&s.env);
    let bob = Address::generate(&s.env);
    s.token_admin.mint(&alice, &100);
    s.client.stake(&alice, &100);

    let result = s.client.try_unstake(&bob, &50);

    assert_eq!(result, Err(Ok(Error::InsufficientStake)));
    assert_eq!(s.client.staked(&alice), 100);
}

#[test]
fn non_positive_amounts_are_rejected() {
    let s = setup();
    let user = Address::generate(&s.env);
    s.token_admin.mint(&user, &100);
    s.client.stake(&user, &100);

    assert_eq!(s.client.try_stake(&user, &0), Err(Ok(Error::InvalidAmount)));
    assert_eq!(s.client.try_stake(&user, &-5), Err(Ok(Error::InvalidAmount)));
    assert_eq!(s.client.try_unstake(&user, &0), Err(Ok(Error::InvalidAmount)));
    assert_eq!(s.client.staked(&user), 100);
}

#[test]
fn stake_requires_the_user_to_authorize() {
    let env = Env::default();
    let issuer = Address::generate(&env);
    let token_id = env.register_stellar_asset_contract_v2(issuer).address();
    let contract_id = env.register(Staking, (token_id,));
    let client = StakingClient::new(&env, &contract_id);
    let user = Address::generate(&env);

    // No authorization was mocked, so the call must be rejected.
    assert!(client.try_stake(&user, &10).is_err());
}
EOF
