  }
  return (
    <p>
      Total staked: <span data-testid="total-staked">{outcome.total}</span>
    </p>
  );
}

export default function StakingPage() {
  return (
    <main>
      <h1>Staking</h1>
      <Suspense fallback={<p>Reading the contract…</p>}>
        <TotalStaked />
      </Suspense>
      <StakeForm />
    </main>
  );
}
