"use client";

import { useRouter } from "next/navigation";
import { useState, type FormEvent } from "react";
import { requestAccess, signAuthEntry, signTransaction } from "@stellar/varial-sdk";
import { staking, type Signer } from "@/lib/contracts";
import { stellar } from "@/lib/stellar";

function errorText(error: unknown): string {
  if (error instanceof Error) return error.message;
  if (error && typeof error === "object" && "message" in error) return String(error.message);
  return String(error);
}

export function StakeForm() {
  const router = useRouter();
  const [address, setAddress] = useState<string | null>(null);
  const [busy, setBusy] = useState(false);
  const [message, setMessage] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);

  async function connect() {
    setError(null);
    try {
      const { address: publicKey, error: walletError } = await requestAccess();
      if (walletError) throw new Error(walletError.message);
      setAddress(publicKey);
    } catch (err) {
      setError(`Could not connect the wallet: ${errorText(err)}`);
    }
  }

  async function onSubmit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    setError(null);
    setMessage(null);
    const data = new FormData(event.currentTarget);
    const raw = String(data.get("amount") ?? "").trim();
    if (!/^[1-9][0-9]*$/.test(raw)) {
      setError("Enter a whole number greater than zero.");
      return;
    }
    if (!address) {
      setError("Connect a wallet first.");
      return;
    }
    const amount = BigInt(raw);

    setBusy(true);
    try {
      const signer: Signer = {
        publicKey: address,
        signTransaction,
        signAuthEntry,
      };
      const tx = await staking(signer).stake({ user: address, amount });
      await tx.signAndSend();
      setMessage(`Staked ${raw}.`);
      // Re-run the server component so the total shows the new amount.
      router.refresh();
    } catch (err) {
      setError(`Stake failed: ${errorText(err)}`);
    } finally {
      setBusy(false);
    }
  }

  return (
    <section>
      <p>
        Network: <code>{stellar.network}</code>
      </p>
      {address ? (
        <p>
          Wallet: <code data-testid="wallet-address">{address}</code>
        </p>
      ) : (
        <button type="button" data-testid="connect-wallet" onClick={connect}>
          Connect wallet
        </button>
      )}

      <form onSubmit={onSubmit}>
        <label>
          Amount to stake (in stroops, 1 XLM = 10,000,000):{" "}
          <input
            type="text"
            name="amount"
            inputMode="numeric"
            autoComplete="off"
            data-testid="stake-amount"
          />
        </label>{" "}
        <button type="submit" data-testid="stake-submit" disabled={busy}>
          {busy ? "Staking…" : "Stake"}
        </button>
      </form>

      {message && <p data-testid="stake-message">{message}</p>}
      {error && <p data-testid="stake-error">{error}</p>}
    </section>
  );
}
